import { IsBoolean, IsIn, IsInt, IsNumber, IsOptional, IsString, Min, MaxLength } from 'class-validator';

export class CriarPlanoDto {
  @IsString()
  @MaxLength(100)
  nome: string;

  @IsNumber()
  @Min(0)
  valor: number;

  @IsIn(['mensal', 'trimestral', 'anual'])
  periodicidade: 'mensal' | 'trimestral' | 'anual';

  // saas = loja multi-tenant; local = instalação individual licenciada
  @IsOptional()
  @IsIn(['saas', 'local'])
  tipo?: 'saas' | 'local';

  @IsOptional()
  @IsInt()
  @Min(1)
  limite_produtos?: number;

  @IsOptional()
  @IsNumber()
  @Min(0)
  piso_faturamento?: number;

  @IsOptional()
  @IsInt()
  @Min(0)
  trial_dias?: number;

  @IsOptional()
  @IsBoolean()
  ativo?: boolean;

  @IsOptional()
  @IsBoolean()
  inclui_delivery?: boolean;

  @IsOptional()
  @IsBoolean()
  inclui_salao?: boolean;

  @IsOptional()
  @IsBoolean()
  inclui_gdoor?: boolean;

  // Cobra comissão sobre vendas sem split PagBank ativo, além da mensalidade
  // (ver PlanosService.buscarComissoesNaoColetadas).
  @IsOptional()
  @IsBoolean()
  cobra_comissao?: boolean;
}

import { IsBoolean, IsIn, IsInt, IsNumber, IsOptional, IsString, Min, MaxLength } from 'class-validator';

export class AtualizarPlanoDto {
  @IsOptional()
  @IsString()
  @MaxLength(100)
  nome?: string;

  @IsOptional()
  @IsNumber()
  @Min(0)
  valor?: number;

  @IsOptional()
  @IsIn(['mensal', 'trimestral', 'anual'])
  periodicidade?: 'mensal' | 'trimestral' | 'anual';

  @IsOptional()
  @IsIn(['saas', 'local'])
  tipo?: 'saas' | 'local';

  // null explicito remove o limite (vira ilimitado)
  @IsOptional()
  @IsInt()
  @Min(1)
  limite_produtos?: number | null;

  // null explicito remove o piso (passa a cobrar sempre)
  @IsOptional()
  @IsNumber()
  @Min(0)
  piso_faturamento?: number | null;

  @IsOptional()
  @IsInt()
  @Min(0)
  trial_dias?: number;

  @IsOptional()
  @IsBoolean()
  ativo?: boolean;

  @IsOptional()
  @IsBoolean()
  inclui_delivery?: boolean;

  @IsOptional()
  @IsBoolean()
  inclui_salao?: boolean;

  @IsOptional()
  @IsBoolean()
  inclui_gdoor?: boolean;

  @IsOptional()
  @IsBoolean()
  cobra_comissao?: boolean;
}

