46	const Modal = ({ plano, planosExistentes, onClose, onSave }) => {
47	  const [form, setForm] = useState(
48	    plano
49	      ? {
50	          nome: plano.nome,
51	          valor: String(plano.valor),
52	          periodicidade: plano.periodicidade,
53	          tipo: plano.tipo ?? 'saas',
54	          limite_produtos: plano.limite_produtos != null ? String(plano.limite_produtos) : '',
55	          piso_faturamento: plano.piso_faturamento != null ? String(plano.piso_faturamento) : '',
56	          trial_dias: String(plano.trial_dias ?? 0),
57	          ativo: plano.ativo,
58	          inclui_delivery: plano.inclui_delivery ?? true,
59	          inclui_salao: plano.inclui_salao ?? false,
60	          inclui_gdoor: plano.inclui_gdoor ?? false,
61	          cobra_comissao: plano.cobra_comissao ?? false,
62	        }
63	      : { ...EMPTY }
64	  );
65	  const isLocal = form.tipo === 'local';
66	  const [salvando, setSalvando] = useState(false);
67	  const [erro, setErro] = useState(null);
68	  const isEdicao = !!plano;
69	
70	  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));
71	
72	  const handleSubmit = async (e) => {
73	    e.preventDefault();
74	    if (!form.nome.trim() || !form.valor) return;
75	
76	    const nomeNormalizado = normalizarNome(form.nome);
77	    const duplicado = (planosExistentes ?? []).find(
78	      (p) => p.id !== plano?.id && normalizarNome(p.nome) === nomeNormalizado
79	    );
80	    if (duplicado) {
81	      setErro(`Já existe um plano chamado "${duplicado.nome}"`);
82	      return;
83	    }
84	
85	    setSalvando(true);
