94	        piso_faturamento: form.piso_faturamento.trim() ? parseFloat(form.piso_faturamento) : null,
95	        trial_dias: form.trial_dias.trim() ? parseInt(form.trial_dias, 10) : 0,
96	        inclui_delivery: form.inclui_delivery,
97	        inclui_salao: form.inclui_salao,
98	        inclui_gdoor: form.inclui_gdoor,
99	        cobra_comissao: form.cobra_comissao,
100	      };
101	      if (isEdicao) {
